async createEncounter(dto: CreateEncounterDto): Promise<Encounter> {
    if (dto.adtType !== AdtType.A01) {
      throw new BadRequestException(
        'Only ADT A01 can create an encounter; use the ADT workflow for A02, A03 and A08',
      );
    }
    this.validateEncounterFields(dto);
    const patient = await this.patientService.getPatientById(dto.patientId);
    if (!patient.active) {
      throw new BadRequestException('Cannot admit an inactive patient');
    }
    const active = await this.encounterRepository.findActiveByPatient(
      dto.patientId,
    );
    if (active) {
      throw new ConflictException(
        `Patient already has an active encounter (id: ${active.id})`,
      );
    }
    const encounter = this.encounterRepository.create({
      ...dto,
      admitDate: new Date(dto.admitDate),
      status: EncounterStatus.ADMITTED,
      ward: dto.ward ?? null,
      transferDate: null,
      dischargeDate: null,
    });
    return this.encounterRepository.save(encounter);
  }

validateEncounterFields(dto: CreateEncounterDto): void {
    if (dto.adtType === AdtType.A01 && !dto.ward) {
      throw new BadRequestException('Ward is required for ADT A01 (admission)');
    }
    if (dto.adtType === AdtType.A02 && !dto.ward) {
      throw new BadRequestException('Ward is required for ADT A02 (transfer)');
    }
    if (dto.adtType === AdtType.A03 && dto.ward) {
      throw new BadRequestException(
        'Ward must not be informed for ADT A03 (discharge)',
      );
    }
    if (dto.adtType === AdtType.A08 && dto.ward) {
      throw new BadRequestException(
        'Ward must not be informed for ADT A08 (update)',
      );
    }
    if (dto.adtType === AdtType.A08 && !dto.patientId) {
      throw new BadRequestException(
        'PatientId is required for ADT A08 (update)',
      );
    }
  }

async listEncountersByPatient(
    patientId: string,
    dto: ListEncountersByPatientDto,
  ): Promise<Encounter[]> {
    await this.patientService.getPatientById(patientId);
    return this.encounterRepository.findByPatient(patientId, dto);
  }

async getEncounterById(id: string): Promise<Encounter> {
    const encounter = await this.encounterRepository.findById(id);
    if (!encounter) {
      throw new NotFoundException(`Encounter with id ${id} not found`);
    }
    return encounter;
  }

async transitionEncounterStatus(
    id: string,
    dto: TransitionEncounterStatusDto,
  ): Promise<Encounter> {
    const encounter = await this.getEncounterById(id);
    const { status: currentStatus } = encounter;
    const { status: nextStatus } = dto;
    const validTransitions: Record<EncounterStatus, EncounterStatus[]> = {
      [EncounterStatus.ADMITTED]: [
        EncounterStatus.TRANSFERRED,
        EncounterStatus.DISCHARGED,
      ],
      [EncounterStatus.TRANSFERRED]: [EncounterStatus.DISCHARGED],
      [EncounterStatus.DISCHARGED]: [],
    };
    if (!validTransitions[currentStatus].includes(nextStatus)) {
      throw new BadRequestException(
        `Invalid status transition from ${currentStatus} to ${nextStatus}`,
      );
    }
    if (nextStatus === EncounterStatus.DISCHARGED) {
      const hasPendingOrders = encounter.orders?.some(
        (order) =>
          order.status === OrderStatus.PENDING ||
          order.status === OrderStatus.IN_PROGRESS,
      );
      if (hasPendingOrders) {
        throw new BadRequestException(
          'Cannot discharge encounter with pending or in-progress orders',
        );
      }
    }
    if (nextStatus === EncounterStatus.TRANSFERRED) {
      if (!dto.ward) {
        throw new BadRequestException('Ward is required for transfer');
      }
      if (dto.ward === encounter.ward) {
        throw new BadRequestException(
          `Transfer requires a different ward. Current ward: ${encounter.ward}`,
        );
      }
    }
    if (nextStatus === EncounterStatus.TRANSFERRED) {
      if (!dto.transferDate) {
        throw new BadRequestException('transferDate is required for transfer');
      }
      const transferDate = new Date(dto.transferDate);
      if (transferDate <= encounter.admitDate) {
        throw new BadRequestException('transferDate must be after admitDate');
      }
      encounter.transferDate = transferDate;
      encounter.ward = dto.ward as Ward;
    }
    if (nextStatus === EncounterStatus.DISCHARGED) {
      if (!dto.dischargeDate) {
        throw new BadRequestException(
          'dischargeDate is required for discharge',
        );
      }
      const dischargeDate = new Date(dto.dischargeDate);
      if (dischargeDate <= encounter.admitDate) {
        throw new BadRequestException('dischargeDate must be after admitDate');
      }
      if (encounter.transferDate && dischargeDate <= encounter.transferDate) {
        throw new BadRequestException(
          'dischargeDate must be after transferDate',
        );
      }
      encounter.dischargeDate = dischargeDate;
    }
    if (
      encounter.adtType === AdtType.A08 &&
      nextStatus !== EncounterStatus.ADMITTED
    ) {
      throw new BadRequestException(
        'ADT A08 encounters cannot have status transitions',
      );
    }
    encounter.status = nextStatus;
    return this.encounterRepository.save(encounter);
  }

async processAdtMessage(
    dto: AdtMessageDto,
  ): Promise<{ patient: Patient; encounter?: Encounter }> {
    if (dto.adtType === AdtType.A01) {
      if (!dto.name || !dto.birthDate || !dto.sex || !dto.admitDate) {
        throw new BadRequestException(
          'A01 requires: name, birthDate, sex, admitDate',
        );
      }
      let patient: Patient;
      try {
        patient = await this.patientService.findByCpfOrFail(dto.cpf);
      } catch (error) {
        if (!(error instanceof NotFoundException)) {
          throw error;
        }
        patient = await this.patientService.createPatient({
          cpf: dto.cpf,
          name: dto.name,
          birthDate: dto.birthDate,
          sex: dto.sex,
          email: dto.email,
          phone: dto.phone,
        });
      }
      const encounter = await this.createEncounter({
        patientId: patient.id,
        adtType: AdtType.A01,
        admitDate: dto.admitDate,
        ward: dto.ward,
      });
      return { patient, encounter };
    }
    if (dto.adtType === AdtType.A02) {
      if (!dto.ward || !dto.transferDate) {
        throw new BadRequestException('A02 requires: ward, transferDate');
      }
      const patient = await this.patientService.findByCpfOrFail(dto.cpf);
      const encounter = await this.encounterRepository.findActiveByPatient(
        patient.id,
      );
      if (!encounter) {
        throw new NotFoundException(
          `No active encounter found for patient with cpf ${dto.cpf}`,
        );
      }
      const transitionDto: TransitionEncounterStatusDto = {
        status: EncounterStatus.TRANSFERRED,
        ward: dto.ward,
        transferDate: dto.transferDate,
      };
      const updated = await this.transitionEncounterStatus(
        encounter.id,
        transitionDto,
      );
      return { patient, encounter: updated };
    }
    if (dto.adtType === AdtType.A03) {
      if (!dto.dischargeDate) {
        throw new BadRequestException('A03 requires: dischargeDate');
      }
      const patient = await this.patientService.findByCpfOrFail(dto.cpf);
      const encounter = await this.encounterRepository.findActiveByPatient(
        patient.id,
      );
      if (!encounter) {
        throw new NotFoundException(
          `No active encounter found for patient with cpf ${dto.cpf}`,
        );
      }
      const transitionDto: TransitionEncounterStatusDto = {
        status: EncounterStatus.DISCHARGED,
        dischargeDate: dto.dischargeDate,
      };
      const updated = await this.transitionEncounterStatus(
        encounter.id,
        transitionDto,
      );
      return { patient, encounter: updated };
    }
    if (dto.adtType === AdtType.A08) {
      if (!dto.name && !dto.birthDate && !dto.sex && !dto.email && !dto.phone) {
        throw new BadRequestException(
          'A08 requires at least one field to update: name, birthDate, sex, email or phone',
        );
      }
      const patient = await this.patientService.findByCpfOrFail(dto.cpf);
      const updated = await this.patientService.updatePatient(patient.id, {
        name: dto.name,
        birthDate: dto.birthDate,
        sex: dto.sex,
        email: dto.email,
        phone: dto.phone,
      });
      return { patient: updated };
    }
    throw new BadRequestException(`Unsupported ADT type: ${dto.adtType}`);
  }

async updateEncounter(
    id: string,
    dto: UpdateEncounterDto,
  ): Promise<Encounter> {
    const encounter = await this.getEncounterById(id);
    if (encounter.status === EncounterStatus.DISCHARGED) {
      throw new BadRequestException('Cannot update a discharged encounter');
    }
    if (dto.admitDate !== undefined) {
      if (encounter.status !== EncounterStatus.ADMITTED) {
        throw new BadRequestException(
          'admitDate can only be updated when encounter is ADMITTED',
        );
      }
      const admitDate = new Date(dto.admitDate);
      const now = new Date();
      if (admitDate > now) {
        throw new BadRequestException('admitDate cannot be a future date');
      }
      if (
        encounter.transferDate &&
        admitDate >= new Date(encounter.transferDate)
      ) {
        throw new BadRequestException('admitDate must be before transferDate');
      }
      encounter.admitDate = admitDate;
    }
    if (dto.ward !== undefined) {
      if (dto.ward === encounter.ward) {
        throw new BadRequestException(
          `Ward is already ${encounter.ward}. Use status transition for transfers`,
        );
      }
      encounter.ward = dto.ward;
    }
    return this.encounterRepository.save(encounter);
  }

async buildEncounterSummary(id: string): Promise<EncounterSummary> {
    const encounter = await this.getEncounterById(id);
    const patient = await this.patientService.getPatientById(
      encounter.patientId,
    );
    const admitDate = new Date(encounter.admitDate);
    const now = new Date();
    const activeDays = Math.floor(
      (now.getTime() - admitDate.getTime()) / (1000 * 60 * 60 * 24),
    );
    const orderSummary = {
      total: 0,
      pending: 0,
      inProgress: 0,
      completed: 0,
      cancelled: 0,
    };
    const resultSummary = {
      total: 0,
      abnormal: 0,
      preliminary: 0,
    };
    for (const order of encounter.orders ?? []) {
      orderSummary.total++;
      if (order.status === OrderStatus.PENDING) orderSummary.pending++;
      else if (order.status === OrderStatus.IN_PROGRESS)
        orderSummary.inProgress++;
      else if (order.status === OrderStatus.COMPLETED) orderSummary.completed++;
      else if (order.status === OrderStatus.CANCELLED) orderSummary.cancelled++;
      for (const result of order.results ?? []) {
        resultSummary.total++;
        if (result.status === ResultStatus.PRELIMINARY) {
          resultSummary.preliminary++;
        }
        const value = Number(result.value);
        const refMin = result.referenceMin !== null ? Number(result.referenceMin) : null;
        const refMax = result.referenceMax !== null ? Number(result.referenceMax) : null;
        const isAbnormal =
          (refMin !== null && value < refMin) ||
          (refMax !== null && value > refMax);
        if (isAbnormal) resultSummary.abnormal++;
      }
    }
    const hasAbnormalResults = resultSummary.abnormal > 0;
    let riskFlag: 'LOW' | 'MEDIUM' | 'HIGH';
    if (hasAbnormalResults && activeDays > 7) {
      riskFlag = 'HIGH';
    } else if (hasAbnormalResults || activeDays > 7) {
      riskFlag = 'MEDIUM';
    } else {
      riskFlag = 'LOW';
    }
    return {
      encounter,
      patient,
      activeDays,
      orders: orderSummary,
      results: resultSummary,
      hasAbnormalResults,
      riskFlag,
    };
  }

async getOrderById(id: string): Promise<Order> {
    const order = await this.orderRepository.findById(id);
    if (!order) {
      throw new NotFoundException(`Order with id ${id} not found`);
    }
    return order;
  }

async createOrder(dto: CreateOrderDto): Promise<Order> {
    const encounter = await this.encounterService.getEncounterById(
      dto.encounterId,
    );
    if (encounter.status === EncounterStatus.DISCHARGED) {
      throw new BadRequestException(
        'Cannot create order for a discharged encounter',
      );
    }
    if (new Date(dto.requestedAt) < new Date(encounter.admitDate)) {
      throw new BadRequestException(
        'Order date cannot be before admission date',
      );
    }
    const existing = await this.orderRepository.existsPendingOrder(
      dto.encounterId,
      dto.examType,
    );
    if (existing) {
      throw new ConflictException(
        'A pending order for this exam already exists',
      );
    }
    const order = this.orderRepository.create({
      ...dto,
      requestedAt: new Date(dto.requestedAt),
      status: OrderStatus.PENDING,
      notes: dto.notes ?? null,
    });
    return this.orderRepository.save(order);
  }

searchOrders(dto: SearchOrdersDto): Promise<Order[]> {
    return this.orderRepository.search(dto);
  }

searchOrdersAdvanced(dto: SearchOrdersAdvancedDto): Promise<PaginatedOrders> {
    return this.orderRepository.searchAdvanced(dto);
  }

async validateOrderResult(
    orderId: string,
    incomingStatus: ResultStatus,
  ): Promise<Order> {
    const order = await this.getOrderById(orderId);
    if (order.status === OrderStatus.CANCELLED) {
      throw new BadRequestException(
        `Cannot add result to a cancelled order (id: ${orderId})`,
      );
    }
    const encounter = await this.encounterService.getEncounterById(
      order.encounterId,
    );
    if (encounter.status === EncounterStatus.DISCHARGED) {
      throw new BadRequestException(
        `Cannot add result to an order from a discharged encounter (id: ${order.encounterId})`,
      );
    }
    const hasFinalResult = order.results?.some(
      (r) => (r as { status: ResultStatus }).status === ResultStatus.FINAL,
    );
    const hasCorrectedResult = order.results?.some(
      (r) => (r as { status: ResultStatus }).status === ResultStatus.CORRECTED,
    );
    if (incomingStatus === ResultStatus.CORRECTED) {
      if (order.status !== OrderStatus.COMPLETED) {
        throw new BadRequestException(
          'Cannot register a CORRECTED result until the order is COMPLETED',
        );
      }
      if (!hasFinalResult || hasCorrectedResult) {
        throw new BadRequestException(
          `Order (id: ${orderId}) must have exactly one final result available for correction`,
        );
      }
      return order;
    }
    if (order.status === OrderStatus.COMPLETED) {
      throw new BadRequestException(
        `Order already completed (id: ${orderId}). Cannot add another result`,
      );
    }
    if (hasFinalResult || hasCorrectedResult) {
      throw new BadRequestException(
        `Order (id: ${orderId}) already has a final or corrected result`,
      );
    }
    if (
      order.status === OrderStatus.PENDING &&
      incomingStatus === ResultStatus.FINAL
    ) {
      throw new BadRequestException(
        'Cannot register a FINAL result for a PENDING order. Order must be IN_PROGRESS first',
      );
    }
    if (order.status === OrderStatus.PENDING) {
      order.status = OrderStatus.IN_PROGRESS;
      return this.orderRepository.save(order);
    }
    if (
      order.status === OrderStatus.IN_PROGRESS &&
      incomingStatus === ResultStatus.FINAL
    ) {
      order.status = OrderStatus.COMPLETED;
      return this.orderRepository.save(order);
    }
    return order;
  }

async cancelOrder(id: string): Promise<Order> {
    const order = await this.getOrderById(id);
    if (order.status === OrderStatus.CANCELLED) {
      throw new BadRequestException(`Order ${id} is already cancelled`);
    }
    order.status = OrderStatus.CANCELLED;
    return this.orderRepository.save(order);
  }

async updateOrder(id: string, dto: UpdateOrderDto): Promise<Order> {
    const order = await this.getOrderById(id);
    if (
      order.status === OrderStatus.CANCELLED ||
      order.status === OrderStatus.COMPLETED
    ) {
      throw new BadRequestException(
        `Cannot update order with status ${order.status}`,
      );
    }
    if (
      order.status === OrderStatus.IN_PROGRESS &&
      dto.requestedBy !== undefined
    ) {
      throw new BadRequestException(
        'Cannot update requestedBy for an order in progress. Only notes can be updated',
      );
    }
    const updateData: Partial<Order> = {};
    if (dto.requestedBy !== undefined) {
      updateData.requestedBy = dto.requestedBy;
    }
    if (dto.notes !== undefined) {
      updateData.notes = dto.notes;
    }
    Object.assign(order, updateData);
    return this.orderRepository.save(order);
  }

async getPatientById(id: string): Promise<Patient> {
    const patient = await this.patientRepository.findById(id);
    if (!patient) {
      throw new NotFoundException(`Patient with id ${id} not found`);
    }
    return patient;
  }

listPatients(): Promise<Patient[]> {
    return this.patientRepository.findAll();
  }

async createPatient(dto: CreatePatientDto): Promise<Patient> {
    const normalizedCpf = dto.cpf.replace(/[.-]/g, '');
    const normalizedEmail = dto.email?.toLowerCase();
    const existingCpf = await this.patientRepository.findByCpf(normalizedCpf);
    if (existingCpf) {
      throw new ConflictException(`CPF ${dto.cpf} already registered`);
    }
    if (normalizedEmail) {
      const existingEmail =
        await this.patientRepository.findByEmail(normalizedEmail);
      if (existingEmail) {
        throw new ConflictException(`Email ${dto.email} already registered`);
      }
    }
    const patient = this.patientRepository.create({
      ...dto,
      cpf: normalizedCpf,
      email: normalizedEmail,
      birthDate: new Date(dto.birthDate),
    });
    return this.patientRepository.save(patient);
  }

async updatePatient(id: string, dto: UpdatePatientDto): Promise<Patient> {
    const patient = await this.getPatientById(id);
    if (dto.email && dto.email.toLowerCase() !== patient.email) {
      const existingEmail = await this.patientRepository.findByEmail(
        dto.email.toLowerCase(),
      );
      if (existingEmail) {
        throw new ConflictException(`Email ${dto.email} already registered`);
      }
    }
    const updateData: Partial<Patient> = {
      ...(dto.name && { name: dto.name }),
      ...(dto.sex && { sex: dto.sex }),
      ...(dto.phone !== undefined && { phone: dto.phone }),
      ...(dto.active !== undefined && { active: dto.active }),
      ...(dto.email && { email: dto.email.toLowerCase() }),
      ...(dto.birthDate && { birthDate: new Date(dto.birthDate) }),
    };
    return this.patientRepository.update(patient, updateData);
  }

async findByCpfOrFail(cpf: string): Promise<Patient> {
    const patient = await this.patientRepository.findByCpf(cpf);
    if (!patient) {
      throw new NotFoundException(`Patient with cpf ${cpf} not found`);
    }
    return patient;
  }

async createResult(dto: CreateResultDto): Promise<Result> {
    await this.orderService.validateOrderResult(dto.orderId, dto.status);
    const result = this.resultRepository.create({
      ...dto,
      resultDate: new Date(dto.resultDate),
      referenceMin: dto.referenceMin ?? null,
      referenceMax: dto.referenceMax ?? null,
      sourceSystem: dto.sourceSystem ?? null,
      notes: dto.notes ?? null,
    });
    return this.resultRepository.save(result);
  }

searchResults(dto: SearchResultsDto): Promise<Result[]> {
    return this.resultRepository.search(dto);
  }

async getResultById(id: string): Promise<Result> {
    const result = await this.resultRepository.findById(id);
    if (!result) {
      throw new NotFoundException(`Result with id ${id} not found`);
    }
    return result;
  }

async buildResultReport(orderId: string): Promise<ResultReport> {
    const order = await this.orderService.getOrderById(orderId);
    const results = await this.resultRepository.findByOrderId(orderId);
    if (results.length === 0) {
      throw new NotFoundException(`No results found for order ${orderId}`);
    }
    const defaultRanges: Partial<
      Record<ExamType, { min: number; max: number }>
    > = {
      [ExamType.GLUCOSE]: { min: 70, max: 99 },
      [ExamType.CREATININE]: { min: 0.6, max: 1.2 },
      [ExamType.TSH]: { min: 0.4, max: 4.0 },
    };
    const summary = {
      total: results.length,
      preliminary: 0,
      final: 0,
      corrected: 0,
      abnormal: 0,
    };
    const items: ResultReportItem[] = results.map((result) => {
      if (result.status === ResultStatus.PRELIMINARY) summary.preliminary++;
      else if (result.status === ResultStatus.FINAL) summary.final++;
      else if (result.status === ResultStatus.CORRECTED) summary.corrected++;
      const refMin =
        result.referenceMin !== null
          ? Number(result.referenceMin)
          : (defaultRanges[order.examType]?.min ?? null);
      const refMax =
        result.referenceMax !== null
          ? Number(result.referenceMax)
          : (defaultRanges[order.examType]?.max ?? null);
      const value = Number(result.value);
      let flag: 'LOW' | 'NORMAL' | 'HIGH' | 'UNKNOWN';
      if (refMin === null && refMax === null) {
        flag = 'UNKNOWN';
      } else if (refMin !== null && value < refMin) {
        flag = 'LOW';
      } else if (refMax !== null && value > refMax) {
        flag = 'HIGH';
      } else {
        flag = 'NORMAL';
      }
      if (flag === 'LOW' || flag === 'HIGH') summary.abnormal++;
      return {
        resultId: result.id,
        examType: order.examType,
        value,
        unit: result.unit,
        status: result.status,
        referenceMin: refMin,
        referenceMax: refMax,
        flag,
        sourceSystem: result.sourceSystem,
        resultDate: result.resultDate,
      };
    });
    return { orderId, examType: order.examType, items, summary };
  }

async updateResult(id: string, dto: UpdateResultDto): Promise<Result> {
    const result = await this.getResultById(id);
    if (result.status === ResultStatus.CORRECTED && dto.status !== undefined) {
      throw new BadRequestException(
        'Cannot change status of a CORRECTED result — it is terminal',
      );
    }
    if (dto.status !== undefined) {
      const validTransitions: Record<ResultStatus, ResultStatus[]> = {
        [ResultStatus.PRELIMINARY]: [
          ResultStatus.FINAL,
          ResultStatus.CORRECTED,
        ],
        [ResultStatus.FINAL]: [ResultStatus.CORRECTED],
        [ResultStatus.CORRECTED]: [],
      };
      if (!validTransitions[result.status].includes(dto.status)) {
        throw new BadRequestException(
          `Invalid status transition from ${result.status} to ${dto.status}`,
        );
      }
    }
    if (dto.value !== undefined && result.status !== ResultStatus.PRELIMINARY) {
      throw new BadRequestException(
        'Cannot update value of a non-preliminary result',
      );
    }
    if (dto.unit !== undefined && result.status !== ResultStatus.PRELIMINARY) {
      throw new BadRequestException(
        'Cannot update unit of a non-preliminary result',
      );
    }
    if (
      dto.referenceMin !== undefined &&
      result.status === ResultStatus.FINAL
    ) {
      throw new BadRequestException(
        'Cannot update referenceMin of a final result',
      );
    }
    if (
      dto.referenceMax !== undefined &&
      result.status === ResultStatus.FINAL
    ) {
      throw new BadRequestException(
        'Cannot update referenceMax of a final result',
      );
    }
    const newMin =
      dto.referenceMin ??
      (result.referenceMin !== null ? Number(result.referenceMin) : null);
    const newMax =
      dto.referenceMax ??
      (result.referenceMax !== null ? Number(result.referenceMax) : null);
    if (newMin !== null && newMax !== null && newMin >= newMax) {
      throw new BadRequestException(
        'referenceMin must be less than referenceMax',
      );
    }
    const updateData: Partial<Result> = {
      ...(dto.status !== undefined && { status: dto.status }),
      ...(dto.value !== undefined && { value: dto.value }),
      ...(dto.unit !== undefined && { unit: dto.unit }),
      ...(dto.referenceMin !== undefined && { referenceMin: dto.referenceMin }),
      ...(dto.referenceMax !== undefined && { referenceMax: dto.referenceMax }),
      ...(dto.notes !== undefined && { notes: dto.notes }),
    };
    Object.assign(result, updateData);
    return this.resultRepository.save(result);
  }
